    "ward.a-dispense-needs-a-positive-quantity": "Dispense के लिए एक धनात्मक मात्रा (positive quantity) और unit होना आवश्यक है।",
    "ward.a-failed-sample-needs-a-reason": "सैंपल के फेल होने का कारण होना आवश्यक है, ताकि वार्ड को पता रहे कि आगे क्या अलग करना है।",
    "ward.a-feed-may-only-claim-a": "एक फीड केवल उसी सोर्स का दावा कर सकती है जिसकी उसे अनुमति दी गई है। एक एक्सपायर या निरस्त (revoked) ऑथराइज़ेशन इसके द्वारा भेजे जाने वाले अगले मैसेज को रिजेक्ट कर देता है, और बताता है कि दोनों में से क्या हुआ था।",
    "ward.a-final-report-needs-an-impression": "Final report में impression होना आवश्यक है; यदि यह तैयार नहीं है तो इसे preliminary के रूप में जारी करें।",
    "ward.a-final-report-needs-an-impression2": "Final report में impression होना आवश्यक है। Preliminary रीडिंग से बदला हुआ impression एक discrepancy के रूप में फ्लैग किया जाता है, इसे कभी भी चुपचाप ओवरराइट नहीं किया जाता है।",
    "ward.a-follow-up-needs-a-reason": "Follow-up के लिए एक कारण होना आवश्यक है।",
    "ward.a-goal-with-no-review-date": "बिना समीक्षा तिथि वाला लक्ष्य ऐसा लक्ष्य है जिस पर कोई वापस ध्यान नहीं देता। प्लान में पहले से मौजूद लक्ष्यों को रखा जाता है।",
    "ward.a-handover-with-nothing-in-it": "बिना किसी जानकारी के handover कोई handover नहीं है।",
    "ward.a-hospital-approved-group-of-orders": "अस्पताल द्वारा स्वीकृत orders का समूह, जिसमें से प्रत्येक की अलग से जांच की जाती है",
    "ward.a-kind-of-record-wardsynq-does": "एक प्रकार का रिकॉर्ड जिसे WardSynQ इंपोर्ट नहीं करता है।",
    "ward.a-link-needs-the-local-patient": "एक लिंक को उस लोकल मरीज की आवश्यकता होती है जिससे वह जुड़ा हुआ है।",
    "ward.a-match-is-a-suggestion-nothing": "मैच एक सुझाव है। जब तक कोई व्यक्ति निर्णय नहीं लेता, कारण नहीं बताता और पुष्टि नहीं करता, तब तक कुछ भी जोड़ा नहीं जाता।",
    "ward.a-named-report-defaults-to-you": "नामित रिपोर्ट डिफ़ॉल्ट रूप से आपके नाम दर्ज होती है; अनाम का अर्थ वही है: रिकॉर्ड सहित किसी को भी यह नहीं बताया जाता कि इसे किसने दर्ज किया है।",
    "ward.a-next-of-kin-or-emergency": "सगे संबंधी या आपातकालीन संपर्क का नंबर होना आवश्यक है; यह वह नाम है जिसे कोई कॉल करता है।",
