    "ward.a-prescription-needs-the-drug-the": "एक प्रिस्क्रिप्शन के लिए दवा, खुराक और यूनिट आवश्यक हैं। तीनों भरें, या उन्हें क्लियर करें।",
    "ward.a-purchase-order": "एक पर्चेज ऑर्डर",
    "ward.a-question-left-unanswered-is-recorded": "अनुत्तरित छोड़े गए प्रश्न को अनुत्तरित के रूप में रिकॉर्ड किया जाता है। सर्वर द्वारा लौटाया गया स्कोर यह बताता है कि यह पूर्ण है या नहीं।",
