    "site.admin.staff.roleNote.admin": "पूर्ण तकनीकी प्रशासन: स्टाफ, वार्ड, बेड, विभाग, कमरे, बिलिंग कॉन्फ़िगरेशन। क्लिनिकल प्रोटोकॉल साइन-ऑफ नहीं।",
    "site.admin.staff.roleNote.doctor": "पूर्ण क्लिनिकल वर्कफ़्लो: कतार, EMR, ऑर्डर, नुस्खे, अपने मरीज।",
    "site.admin.staff.roleNote.nurse": "डेस्क पर कतार का संचालन, वाइटल्स रिकॉर्ड करना, बेडसाइड पर दवाएं देना (eMAR)। कोई नुस्खा नहीं लिखना।",
    "site.admin.staff.roleNote.reception": "मरीजों का पंजीकरण और चेक-इन, डॉक्टर को असाइन करना। चार्ट पढ़ सकते हैं, इसे संपादित नहीं कर सकते।",
    "site.admin.staff.roleNote.pharmacy": "दवा के ऑर्डरों को पढ़ना और वितरित करना, चार्ट के विरुद्ध ऑर्डर सत्यापित करना। कोई कंसल्टेशन नोट नहीं।",
    "site.admin.staff.roleNote.lab": "ऑर्डर किए गए परीक्षण देखना और परिणाम जारी करना। कोई अन्य चार्ट पहुंच नहीं।",
    "site.admin.staff.roleNote.billing": "चार्ज, इनवॉइस और क्लेम पढ़ना। भुगतान स्वीकार नहीं कर सकते (इसके लिए कैशियर देखें)।",
    "site.admin.staff.roleNote.him": "सूचना-जारी करने के अनुरोधों का निर्णय और रिकॉर्ड करने के लिए चार्ट पढ़ना।",
    "site.admin.staff.roleNote.bloodBank": "केवल क्रॉसमैच, जारी करना और ट्रांसफ्यूजन प्रशासित करना।",
    "site.admin.staff.roleNote.radiographer": "इमेजिंग अध्ययन प्राप्त करना। चार्ट पढ़ सकते हैं, रिपोर्ट फ़ाइल या अध्ययन प्रोटोकॉल नहीं बना सकते।",
    "site.admin.staff.roleNote.radiologist": "इमेजिंग अध्ययनों का प्रोटोकॉल और रिपोर्ट बनाना (वही अधिकार जो लैब परिणाम जारी करने में उपयोग होता है)। कोई अन्य चार्ट राइट नहीं।",
    "site.admin.staff.roleNote.obstetrician": "एक डॉक्टर जो PCPNDT Form F और MTP रजिस्टर भी बनाए रखता है।",
    "site.admin.staff.roleNote.publicHealth": "Public health नोडल अधिकारी: चार्ट पढ़ता है और notifiable disease रजिस्टर व साप्ताहिक IHIP एक्सपोर्ट बनाए रखता है।",
    "site.admin.staff.roleNote.supervisor": "OPD कतार का संचालन करता है और चार्ट पढ़ता है। अपने दायरे के विभागों के लिए स्टोर इंडेंट स्वीकृत करता है।",
    "site.admin.staff.roleNote.storeKeeper": "जनरल स्टोर का संचालन करता है: सामग्री, स्टोर स्थान, स्वीकृत इंडेंट जारी करना, प्राप्त करना और ऑर्डर देना। चार्ट का एक्सेस नहीं।",
    "site.admin.staff.roleNote.biomedicalEngineer": "एसेट रजिस्टर, प्रिवेंटिव मेंटेनेंस, कैलिब्रेशन और जॉब कार्ड बनाए रखता है। चार्ट का एक्सेस नहीं।",
