    "site.admin.seed.treatUnapproved": "प्रत्येक आइटम को अनअप्रोव्ड (UNAPPROVED) मानें।",
    "site.admin.seed.intro": "WardSynQ के साथ क्लिनिकल सामग्री भेजी गई। प्रत्येक आइटम तब तक UNAPPROVED है जब तक {signatory} इसकी सटीक वर्तमान सामग्री को साइन ऑफ नहीं कर देता। साइन करने से साइन-ऑफ रिकॉर्ड होता है; यह किसी भी सुरक्षा जांच के व्यवहार को नहीं बदलता है।",
