    "site.admin.smart.intro1": "बाहरी एप्लिकेशन जिन्हें यह अस्पताल SMART on FHIR के जरिए अपने रिकॉर्ड पढ़ने की अनुमति देता है: एक ऐप जिसका उपयोग क्लिनिशियन करता है (सार्वजनिक), या एक पंजीकृत सिस्टम जिसके पास कुंजी है (बैकएंड)।",
    "site.admin.smart.intro2": "पंजीकरण अनुमत सूची है: एक ऐप जो यहाँ सूचीबद्ध नहीं है उसे कुछ नहीं मिलता है, और किसी ऐप को हटाने से उसके टोकन तुरंत बंद हो जाते हैं। स्विच को बंद करने से हर ऐप के लिए SMART का दरवाजा बंद हो जाता है।",
